import re

roman_numeral = re.compile(r'M{0,3}(?:CM|CD|D?C{0,3})(?:XC|XL|L?X{0,3})(?:IX|IV|V?I{0,3})')
reference_definition = re.compile(r'^[ \t]{0,3}\[(?:\^[^\]\r\n]+|[^\]\r\n]+)\]:[ \t]*(?:<[^>\r\n]*>|\S+)(?:[ \t]+(?:"[^\r\n]*"|\'[^\r\n]*\'|\([^\r\n]*\)))?[ \t]*(?:\r?\n)?$')
fence_open = re.compile(r'^([ \t]*)(`{3,}|~{3,})([^\r\n]*)$')
url_pattern = re.compile(r'(?i:https?://|www\.)[^\s"<>]*')


def is_escaped(text, index):
    count = 0
    index -= 1
    while index >= 0 and text[index] == '\\':
        count += 1
        index -= 1
    return count % 2 == 1


def find_balanced(text, start, opening, closing):
    if start >= len(text) or text[start] != opening:
        return None
    depth = 0
    index = start
    while index < len(text):
        character = text[index]
        if character == '\\':
            index += 2
            continue
        if character == opening:
            depth += 1
        elif character == closing:
            depth -= 1
            if depth == 0:
                return index
        index += 1
    return None


def is_citation_label(label):
    normalized = ' '.join(label.split()).casefold()
    if normalized in {'citation needed', 'edit'}:
        return True
    if re.fullmatch(r'note\s+\d+', normalized):
        return True
    if re.fullmatch(r'\d+(?:\s*[-–]\s*\d+|\s*,\s*\d+)*', label):
        return True
    return label.isupper() and label != '' and roman_numeral.fullmatch(label) is not None


def remove_citations(text):
    output = []
    index = 0
    while index < len(text):
        if text.startswith('[[', index) and not is_escaped(text, index):
            end = text.find(']]', index + 2)
            if end != -1 and is_citation_label(text[index + 2:end]):
                index = end + 2
                continue
        if text[index] == '[' and not is_escaped(text, index):
            end = text.find(']', index + 1)
            if end != -1 and is_citation_label(text[index + 1:end]):
                index = end + 1
                continue
        output.append(text[index])
        index += 1
    return ''.join(output)


def remove_reference_definitions(text):
    return ''.join('' if reference_definition.match(line) else line for line in text.splitlines(keepends=True))


def remove_markdown_links(text):
    output = []
    index = 0
    while index < len(text):
        image = text.startswith('![', index) and not is_escaped(text, index)
        opening = index + 1 if image else index
        if opening < len(text) and text[opening] == '[' and not is_escaped(text, opening):
            label_end = find_balanced(text, opening, '[', ']')
            if label_end is not None:
                if label_end + 1 < len(text) and text[label_end + 1] == '(':
                    destination_end = find_balanced(text, label_end + 1, '(', ')')
                    if destination_end is not None:
                        output.append(text[opening + 1:label_end])
                        index = destination_end + 1
                        continue
                if label_end + 1 < len(text) and text[label_end + 1] == '[':
                    reference_end = find_balanced(text, label_end + 1, '[', ']')
                    if reference_end is not None:
                        output.append(text[opening + 1:label_end])
                        index = reference_end + 1
                        continue
        output.append(text[index])
        index += 1
    return ''.join(output)


def remove_html(text):
    output = []
    index = 0
    while index < len(text):
        if text.startswith('<!--', index):
            end = text.find('-->', index + 4)
            if end != -1:
                index = end + 3
                continue
        if text[index] == '<' and index + 1 < len(text):
            cursor = index + 1
            if text[cursor] == '/':
                cursor += 1
            if cursor < len(text) and (text[cursor].isalpha() or text[cursor] in '!?'):
                quote = None
                while cursor < len(text):
                    character = text[cursor]
                    if quote is not None:
                        if character == '\\':
                            cursor += 2
                            continue
                        if character == quote:
                            quote = None
                    elif character in "\"'":
                        quote = character
                    elif character == '>':
                        index = cursor + 1
                        break
                    cursor += 1
                else:
                    output.append(text[index])
                    index += 1
                    continue
                continue
        output.append(text[index])
        index += 1
    return ''.join(output)


def trim_url(candidate):
    while candidate and candidate[-1] in '.,;:!?':
        candidate = candidate[:-1]
    pairs = {')': '(', ']': '[', '}': '{'}
    while candidate and candidate[-1] in pairs and candidate.count(candidate[-1]) > candidate.count(pairs[candidate[-1]]):
        candidate = candidate[:-1]
    return candidate


def remove_urls(text):
    output = []
    index = 0
    while index < len(text):
        match = url_pattern.match(text, index)
        if match is not None:
            candidate = trim_url(match.group(0))
            if candidate:
                index += len(candidate)
                continue
        output.append(text[index])
        index += 1
    return ''.join(output)


def remove_markup_markers(text):
    text = re.sub(r'(?m)^([ \t]{0,3})#{1,6}[ \t]+', r'\1', text)
    text = re.sub(r'(?m)^([ \t]*)[*+-][ \t]+', r'\1', text)
    text = re.sub(r'(?<!\w)\*{1,3}(?=\S)', '', text)
    text = re.sub(r'(?<=\S)\*{1,3}(?!\w)', '', text)
    return text


def make_token(index, text, protected):
    while True:
        token = '\ue000INLINE_CODE_' + str(index) + '_' + str(len(protected)) + '\ue001'
        if token not in text and all(token not in value for value in protected):
            return token
        index += 1


def protect_inline_code(text):
    protected = []
    output = []
    index = 0
    token_index = 0
    while index < len(text):
        if text[index] == '`' and not is_escaped(text, index):
            end_run = index
            while end_run < len(text) and text[end_run] == '`':
                end_run += 1
            delimiter = text[index:end_run]
            closing = text.find(delimiter, end_run)
            if closing != -1:
                token = make_token(token_index, text, protected)
                token_index += 1
                protected.append((token, text[end_run:closing]))
                output.append(token)
                index = closing + len(delimiter)
                continue
        output.append(text[index])
        index += 1
    return ''.join(output), protected


def restore_inline_code(text, protected):
    for token, value in protected:
        text = text.replace(token, value)
    return text


def process_prose(text):
    text, protected = protect_inline_code(text)
    previous = None
    while previous != text:
        previous = text
        text = remove_reference_definitions(text)
        text = remove_markdown_links(text)
        text = remove_html(text)
        text = remove_citations(text)
        text = re.sub(r'\[\^[^\]\r\n]*\]', '', text)
        text = text.replace('[[]]', '').replace('[]', '')
        text = remove_urls(text)
        text = remove_markup_markers(text)
    return restore_inline_code(text, protected)


def is_closing_fence(line, delimiter):
    character = re.escape(delimiter[0])
    pattern = r'[ \t]*' + character + r'{' + str(len(delimiter)) + r',}[ \t]*(?:\r?\n)?'
    return re.fullmatch(pattern, line) is not None


def is_opening_fence(line):
    match = fence_open.match(line)
    if match is None:
        return None
    delimiter = match.group(2)
    info = match.group(3)
    if delimiter[0] == '`' and '`' in info:
        return None
    return delimiter


def sanitize(text):
    output = []
    prose = []
    delimiter = None

    def flush_prose():
        if prose:
            output.append(process_prose(''.join(prose)))
            prose.clear()

    for line in text.splitlines(keepends=True):
        if delimiter is not None:
            if is_closing_fence(line, delimiter):
                delimiter = None
            else:
                output.append(line)
            continue
        opening = is_opening_fence(line)
        if opening is not None:
            flush_prose()
            delimiter = opening
        else:
            prose.append(line)
    if delimiter is not None:
        raise ValueError('Unclosed fenced code block in uploads/char.txt')
    flush_prose()
    return ''.join(output)


def main():
    try:
        with open('uploads/char.txt', encoding='utf-8') as input_file:
            text = input_file.read()
    except FileNotFoundError as error:
        raise SystemExit('Input file not found: uploads/char.txt') from error
    except UnicodeDecodeError as error:
        raise SystemExit('Input file is not valid UTF-8: uploads/char.txt') from error
    except OSError as error:
        raise SystemExit('Unable to read uploads/char.txt: ' + str(error)) from error
    try:
        sanitized = sanitize(text)
    except ValueError as error:
        raise SystemExit(str(error)) from error
    try:
        with open('char_sanitized.txt', 'w', encoding='utf-8') as output_file:
            output_file.write(sanitized)
            output_file.flush()
    except OSError as error:
        raise SystemExit('Unable to write char_sanitized.txt: ' + str(error)) from error
    print('done; in_code end: False')


if __name__ == '__main__':
    main()
